import re

def inspect_table(connection,schema,table):
    if any(not isinstance(name,str) or not re.fullmatch(r'[a-z][a-z0-9_]{0,47}',name) for name in (schema,table)):raise ValueError('approved literal identifiers required')
    with connection.cursor() as cursor:
        cursor.execute('SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s ORDER BY ORDINAL_POSITION',(schema,table))
        columns=[{'name':name,'type':kind,'nullable':nullable=='YES'} for name,kind,nullable in cursor.fetchall()]
        if not columns:raise ValueError('visible existing table required')
        cursor.execute('SELECT COUNT(*) FROM `'+schema+'`.`'+table+'`');count=int(cursor.fetchone()[0])
    return {'schema':schema,'table':table,'columns':columns,'rows':count}
```

