    if row is None:raise ValueError('approved digest missing')
    return {'schema':schema,'digest':digest,'count':int(row[0]),'timer_ps':int(row[1]),'rows_examined':int(row[2])}

def window(before,after):
    if (before['schema'],before['digest'])!=(after['schema'],after['digest']):raise ValueError('digest identity changed')
    count=after['count']-before['count'];timer=after['timer_ps']-before['timer_ps'];rows=after['rows_examined']-before['rows_examined']
    if min(count,timer,rows)<0:raise ValueError('counter reset; new baseline required')
    return {'executions':count,'total_seconds':timer/1e12,'average_seconds':timer/count/1e12 if count else None,'rows_examined':rows}
